import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const sources = [
  'src/core/geometry.js',
  'src/core/history.js',
  'src/core/io.js',
  'src/core/pixels.js',
  'src/core/recovery.js',
  'src/core/layer-styles.js',
  'src/core/state.js',
  'src/core/color.js',
  'src/core/pixel-worker.js',
  'src/core/render.js',
  'src/adapters/psd.js',
  'src/main.js',
];

function stripModules(source, filename) {
  let text = source
    .replace(/^\s*import\s+[\s\S]*?from\s+['\"][^'\"]+['\"];?\s*$/gm, '')
    .replace(/^\s*import\s+['\"][^'\"]+['\"];?\s*$/gm, '')
    .replace(/^\s*export\s+(?=(?:async\s+)?function\b|class\b|const\b|let\b|var\b)/gm, '');
  if (/^\s*(?:import|export)\b/m.test(text)) {
    throw new Error(`Unsupported module syntax remains in ${filename}`);
  }
  return text.trim();
}

const chunks = [];
for (const file of sources) {
  const source = await readFile(resolve(root, file), 'utf8');
  chunks.push(`// ---- ${file} ----\n${stripModules(source, file)}`);
}
const banner = `/* ZeTer Photo Editor browser bundle. Generated by tools/build-bundle.mjs. */\n(function(){\n'use strict';\n`;
const footer = `\n})();\n`;
await writeFile(resolve(root, 'src/app.bundle.js'), banner + chunks.join('\n\n') + footer, 'utf8');
console.log('Built src/app.bundle.js');